mapper.select:
SELECT expires_at
FROM user_agent_permission
WHERE user_id = #{userId}
  AND agent_id = #{agentId}

SELECT expires_at
FROM user_knowledge_permission
WHERE user_id = #{userId}
  AND knowledge_repository_id = #{repositoryId}

mapper.delete:
DELETE
FROM user_agent_permission
WHERE agent_id = #{agentId}
  AND user_id = #{userId}

DELETE
FROM user_knowledge_permission
WHERE knowledge_repository_id = #{repositoryId}
  AND user_id = #{userId}

mapper.select:
SELECT is_public
FROM agent_access_config
WHERE agent_id = #{agentId}

SELECT is_public
FROM knowledge_repository
WHERE id = #{repositoryId}

mapper.update:
UPDATE agent_access_config
SET is_public  = #{isPublic},
    updated_at = #{now}
WHERE agent_id = #{agentId}

UPDATE knowledge_repository
SET is_public  = #{isPublic},
    updated_at = #{now}
WHERE id = #{repositoryId}

mapper.select:
SELECT user_id
FROM user_knowledge_permission
WHERE knowledge_repository_id = #{repositoryId}

mapper.delete:
DELETE
FROM user_knowledge_permission
WHERE user_id = #{userId}
  AND knowledge_repository_id = #{repositoryId}

mapper.select:
SELECT id, creator_user_id AS creatorUserId, is_public AS isPublic, repo_code AS repoCode, type, protocol, enabled, update_interval_minutes AS updateIntervalMinutes, status, remote_url AS remoteUrl, default_branch AS defaultBranch, last_revision AS lastRevision, last_revision_message AS lastRevisionMessage, last_revision_author AS lastRevisionAuthor, last_revision_time AS lastRevisionTime, last_sync_time AS lastSyncTime, last_error AS lastError, protocol_config::text AS protocolConfig, display_name AS displayName, metadata_config::text AS metadataConfig, credential_config_cipher AS credentialConfigCipher, created_at AS createdAt, updated_at AS updatedAt FROM knowledge_repository
WHERE (creator_user_id = #{userId} OR is_public = true OR id IN #{id}
)
ORDER BY created_at DESC
